    CVolString rg_jsZhi2;
    rg_jsZhi2 = MCPCommandServer::CDPExecuteJSByFrame (Browser, ParamJSON, rg_jsMa1, 10000);
    CVolString rg_JiaoYanKuangJia;
    rg_JiaoYanKuangJia = _T ("");
    if (yyjson_is_null(ParamJSON.data().GetObject()) == FALSE)
    {
        rg_JiaoYanKuangJia = MCPCommandServer::YyjsonGetText (ParamJSON, _CT2 (_T ("frame_id")));
    }
    if (MCPCommandServer::IsBy (rg_jsZhi2, _CT2 (_T ("{\"error\""))) && rg_JiaoYanKuangJia != _T ("") && rg_JiaoYanKuangJia != _T ("main") && rg_JiaoYanKuangJia != _T ("主框架"))
    {
        return (MCPResponseBuilder::CommandFailure (CommandID, OperationName + _T ("未执行: ") + rg_jsZhi2));
    }
    if (rg_jsZhi2 == _T ("__MCP_NO_ELEM__"))
    {
        if (rg_JiaoYanKuangJia != _T ("") && rg_JiaoYanKuangJia != _T ("main") && rg_JiaoYanKuangJia != _T ("主框架"))
        {
            return (MCPResponseBuilder::CommandFailure (CommandID, OperationName + _T ("未执行: 框架(") + rg_JiaoYanKuangJia + _T (")内匹配到 0 个元素 -> ") + Selector + _T (" | 建议: 先用 browser_get_frames 确认框架标识, 再用 browser_dom_query {frame_id} 确认能取到该元素")));
        }
        return (MCPResponseBuilder::CommandFailure (CommandID, OperationName + _T ("未执行: 选择器在当前页面匹配到 0 个元素 -> ") + Selector + _T (" | 建议: 先用 browser_snapshot 或 browser_get_forms 获取页面可用元素/选择器; 若元素在 iframe 内请传 frame_id(取自 browser_get_frames)")));
    }
    return (_T (""));
